  console.error("STRIPE_SECRET_KEY is a live key. Set ALLOW_LIVE_REFUNDS=1 to issue real refunds.");
  process.exit(1);
}

const orders = loadOrders(env("ORDERS_FILE", "orders.json"));
const state = new StateStore(env("STATE_FILE", "state.json"));
